import datetime
import hashlib
import json
from pathlib import Path
import re
import subprocess
import yaml

ROOT=Path('/workspace/cp-library')
OUT=ROOT/'test/benchmark/results/fps_round3_validation'
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def split_front(text):
 m=re.match(r'\A---\r?\n(.*?)\r?\n---(?:\r?\n|\Z)',text,re.S)
 return (yaml.safe_load(m[1]),text[m.end():]) if m else (None,text)
def list_git(args):return subprocess.check_output(['git',*args],cwd=ROOT,text=True).splitlines()
headers=sorted(p.relative_to(ROOT).as_posix() for d in ('components','convolution','fps','data_structure','graph','math','string') for p in (ROOT/d).rglob('*.hpp'))
docs=sorted((ROOT/'docs').rglob('*.md'))
changed=set(list_git(['diff','--name-only','--diff-filter=ACMRT']))|set(list_git(['ls-files','--others','--exclude-standard']))
bench=sorted(ROOT/p for p in changed if p.startswith('test/benchmark/') and p.endswith('.md'))
scanned=[ROOT/'README.md',*docs,*bench]
before={str(p.relative_to(ROOT)):sha(p) for p in scanned}
metadata_errors=[];targets={};body_mismatches=[];liquid=[];links=[]
for p in docs:
 name=str(p.relative_to(ROOT))
 try:data,body=split_front(p.read_text())
 except Exception as e:metadata_errors.append(dict(path=name,reason=str(e)));continue
 if not isinstance(data,dict) or not isinstance(data.get('title'),str) or not data['title'].strip():metadata_errors.append(dict(path=name,reason='missing/invalid metadata title'));continue
 target=data.get('documentation_of')
 if isinstance(target,str):
  target=target.removeprefix('//').removeprefix('/')
  if not (ROOT/target).is_file():metadata_errors.append(dict(path=name,reason='missing documentation_of target',target=target))
  targets.setdefault(target,[]).append(name)
  generated=ROOT/'.verify-helper/markdown'/f'{target}.md'
  if not generated.is_file():body_mismatches.append(dict(path=name,reason='missing generated page'))
  elif split_front(generated.read_text())[1]!=body:body_mismatches.append(dict(path=name,reason='generated body differs from final source'))
 elif target is not None:metadata_errors.append(dict(path=name,reason='invalid documentation_of'))
for h in headers:
 if h not in targets:metadata_errors.append(dict(header=h,reason='library has no doc'))
for target,paths in targets.items():
 if len(paths)>1:metadata_errors.append(dict(target=target,reason='duplicate documentation target',paths=paths))
for p in scanned:
 text=p.read_text();name=str(p.relative_to(ROOT))
 for found in re.finditer(r'\{\{|\{%\s*(?!raw|endraw)',text):liquid.append(dict(path=name,line=text.count('\n',0,found.start())+1,token=found[0]))
 rendered=re.sub(r'```[^\n]*\n.*?```|~~~[^\n]*\n.*?~~~|`[^`\n]*`',lambda m:''.join('\n' if c=='\n' else ' ' for c in m[0]),text,flags=re.S)
 for match in re.finditer(r'\[[^\]]*\]\(([^)]+)\)',rendered):
  target=match[1].strip().strip('<>').split('#',1)[0]
  if not target:continue
  if target.startswith('https://qandori.github.io/cp-library/') and target.endswith('.hpp.html'):local=ROOT/target.removeprefix('https://qandori.github.io/cp-library/').removesuffix('.html')
  elif re.match(r'[a-zA-Z][a-zA-Z0-9+.-]*:',target) or target.startswith('//'):continue
  else:local=ROOT/target.lstrip('/') if target.startswith('/') else p.parent/target
  if not local.exists():links.append(dict(path=name,target=target,line=text.count('\n',0,match.start())+1))
readme=(ROOT/'README.md').read_text();entries=set(re.findall(r'`((?:components|convolution|fps|data_structure|graph|math|string)/[^`]+\.hpp)`',readme))
omissions=sorted(set(headers)-entries)
old_readme=subprocess.check_output(['git','show','HEAD:README.md'],cwd=ROOT,text=True)
preexisting=all(name not in old_readme for name in omissions)
after={str(p.relative_to(ROOT)):sha(p) for p in scanned}
result=dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),library_headers=len(headers),documentation_pages=len(docs),new_or_changed_benchmark_markdown_count=len(bench),generated_body_comparisons=len(targets),metadata_errors=metadata_errors,generated_body_mismatches=body_mismatches,liquid_source_occurrences=liquid,unresolved_local_links=links,headers_without_readme_entries=omissions,readme_omissions_preexisting=preexisting,existing_internal_readme_omissions_note='Three internal helpers had no README entry before this round; all new public/component entries are present.',source_sha256=after,source_hashes_unchanged_during_audit=before==after,scope='README, all source docs, and all new/modified benchmark Markdown; local explicit Markdown targets and own-site hpp.html targets are checked. Remote URLs, anchors and reference-style Markdown links are not fetched or validated. Generated library body text is compared byte-for-byte after YAML front matter. Benchmark reports may subsequently change numerical content; source docs and README are frozen.')
result['success']=not any((metadata_errors,body_mismatches,liquid,links)) and preexisting and before==after
(OUT/'docs_final_audit.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({k:v for k,v in result.items() if k!='source_sha256'},ensure_ascii=False,indent=2))
